import itertools
from collections import deque

def solve(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    orbits = []
    seen = set()

    # Orbits
    for p in perms:
        if p not in seen:
            orbit = []
            curr = p
            for _ in range(n):
                orbit.append(curr)
                seen.add(curr)
                curr = curr[1:] + (curr[0],)
            orbits.append(tuple(sorted(orbit)))

    # Map each permutation to its orbit index
    perm_to_orbit = {}
    for i, orbit in enumerate(orbits):
        for p in orbit:
            perm_to_orbit[p] = i

    # Generators
    # s_i = swap positions i and i+1 (0-indexed)
    # s_{n-1} = swap positions n-1 and 0
    generators = []
    for i in range(n - 1):
        def make_swap(i, j):
            def swap(p):
                res = list(p)
                res[i], res[j] = res[j], res[i]
                return tuple(res)
            return swap
        generators.append(make_swap(i, i+1))

    # last swap: swap n-1 and 0
    def swap_last(n):
        def swap(p):
            res = list(p)
            res[n-1], res[0] = res[0], res[n-1]
            return tuple(res)
        return swap
    generators.append(swap_last(n))

    # Orbit graph
    adj = [set() for _ in range(len(orbits))]
    for i, orbit in enumerate(orbits):
        p = orbit[0]
        for gen in generators:
            new_p = gen(p)
            new_orbit_idx = perm_to_orbit[new_p]
            if new_orbit_idx != i:
                adj[i].add(new_orbit_idx)

    # BFS for diameter
    max_dist = 0
    for start_node in range(len(orbits)):
        distances = [-1] * len(orbits)
        distances[start_node] = 0
        queue = deque([start_node])
        while queue:
            u = queue.popleft()
            max_dist = max(max_dist, distances[u])
            for v in adj[u]:
                if distances[v] == -1:
                    distances[v] = distances[u] + 1
                    queue.append(v)
    return max_dist

